247	    /**
248	     * Build a member id formatted '<REGION><FY><HASH8><CHK>', where REGION is the region derived from
249	     * the owner's postcode (see {@link LocalityResolver#resolveFromPostcode}), FY is the two-digit
250	     * fiscal year of the owner's registration date, HASH8 is the first eight upper-case hex characters
251	     * of the SHA-256 digest of the owner's normalized telephone concatenated with the last name, and
252	     * CHK is a single Luhn check digit over the digits of '<REGION><FY><HASH8>' (e.g. 'NSW271A2B3C4D5';
253	     * see {@link MemberId#of}). Two distinct owners whose '(region, fiscal year, telephone, lastName)'
254	     * hash alike would otherwise share an id; when the computed id collides with an existing owner's
255	     * member id, '-<n>' is appended with the smallest n of 2 or more that makes it unique (see
256	     * {@link #deduplicateMemberId}).
257	     */
258	    private String generateMemberId(Owner owner) {
259	        String region = LocalityResolver.resolveFromPostcode(owner.getPostcode());
260	        String id = MemberId.of(region, owner.getRegistrationDate(), owner.getTelephone(), owner.getLastName());
261	        return deduplicateMemberId(id);
262	    }
263	
264	    /**
265	     * Returns {@code id} unchanged when no existing owner already carries it, otherwise the id with
266	     * '-<n>' appended, choosing the smallest n of 2 or more that makes the result unique among existing
267	     * owners' member ids.
268	     */
269	    private String deduplicateMemberId(String id) {
270	        Set<String> existing = ownerRepository.findAll().stream()
271	            .map(Owner::getMemberId)
272	            .filter(Objects::nonNull)
273	            .collect(Collectors.toSet());
274	        if (!existing.contains(id)) {
275	            return id;
276	        }
277	        for (int n = 2; ; n++) {
278	            String candidate = id + "-" + n;
279	            if (!existing.contains(candidate)) {
280	                return candidate;
281	            }
282	        }
283	    }
