78	
79	    /**
80	     * Dedicated audit logger. A single line is emitted here on each successful owner create,
81	     * carrying the new owner's id, member id and registration date.
82	     */
83	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
84	
85	    /**
86	     * Dedicated notification logger. A single line is emitted here on each successful owner create,
87	     * enqueuing the new owner's welcome notification. The line carries the owner's id and its unified
