395	    /**
396	     * Reads the optional {@code Idempotency-Key} header from the current request. The generated
397	     * {@code addOwner} signature carries only the request body, so the header is pulled from the
398	     * request bound to the current thread. Returns the trimmed key, or {@code null} when the header is
399	     * absent or blank (in which case the create proceeds normally, without idempotent replay).
400	     *
401	     * @return the non-blank idempotency key, or {@code null} when none was supplied
402	     */
403	    private String idempotencyKey() {
404	        if (!(RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attributes)) {
405	            return null;
406	        }
407	        String key = attributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
408	        return isBlank(key) ? null : key.trim();
409	    }
