411	    /**
412	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city} or
413	     * {@code telephone} is missing (null) or blank (empty or whitespace only). Bean Validation on
414	     * the request body already rejects null and empty values, but permits whitespace-only strings
415	     * for fields without a stricter pattern (e.g. {@code city}, {@code address}); this guard closes
416	     * that gap so every required field must carry a non-blank value.
417	     *
418	     * @param ownerFieldsDto the submitted owner fields
419	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
420	     */
421	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
422	        List<String> missing = new ArrayList<>();
423	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
424	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
425	        if (isBlank(ownerFieldsDto.getAddressLine1()) && isBlank(ownerFieldsDto.getAddress())) {
426	            missing.add("address");
427	        }
428	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
429	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
430	        if (!missing.isEmpty()) {
431	            throw new InvalidOwnerFieldsException(missing);
432	        }
433	    }
