463	    /**
464	     * Normalizes the submitted address on create to its canonical form (see
465	     * {@link AddressNormalizer#normalize}) and writes it back onto the request so it is the value
466	     * stored and returned, and the form every later address comparison (the required-field check,
467	     * household duplicate detection and the shared household id) is judged on. The structured fields
468	     * are preferred: {@code addressLine1} and the optional {@code addressLine2} are each normalized in
469	     * place, and the flat {@code address} is set to the {@linkplain #composedAddress composed} value
470	     * derived from them when a structured {@code addressLine1} is present, falling back to the
471	     * normalized flat {@code address} otherwise. Any absent field is left absent so
472	     * {@link #rejectBlankOwnerFields} still reports a wholly missing address; a value that is blank
473	     * after normalization likewise reduces to the empty string and is rejected there.
474	     *
475	     * @param ownerFieldsDto the submitted owner fields
476	     */
477	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
478	        String addressLine1 = AddressNormalizer.normalizeOrNull(ownerFieldsDto.getAddressLine1());
479	        String addressLine2 = AddressNormalizer.normalizeOrNull(ownerFieldsDto.getAddressLine2());
480	        String flatAddress = AddressNormalizer.normalizeOrNull(ownerFieldsDto.getAddress());
481	        ownerFieldsDto.setAddressLine1(addressLine1);
482	        ownerFieldsDto.setAddressLine2(addressLine2);
483	        ownerFieldsDto.setAddress(composedAddress(addressLine1, addressLine2, flatAddress));
484	    }
485	
486	    /**
487	     * Composes the flat {@code address} an owner should carry from its (already normalized) address
488	     * fields, preferring the structured form. When a non-blank {@code addressLine1} is present the
489	     * composed address is {@code addressLine1}, with a single space and {@code addressLine2} appended
490	     * when {@code addressLine2} is present; otherwise the flat {@code address} is used unchanged. This
491	     * is the single value every later reader of the address (the required-field check, household
492	     * duplicate detection and the shared household id) is judged on.
493	     *
494	     * @param addressLine1 the normalized first address line, or {@code null}/blank when absent
495	     * @param addressLine2 the normalized second address line, or {@code null}/blank when absent
496	     * @param flatAddress  the normalized flat address, or {@code null}/blank when absent
497	     * @return the composed flat address, or {@code null} when no address form was supplied
498	     */
499	    private String composedAddress(String addressLine1, String addressLine2, String flatAddress) {
500	        if (isBlank(addressLine1)) {
501	            return flatAddress;
502	        }
503	        if (isBlank(addressLine2)) {
504	            return addressLine1;
505	        }
506	        return addressLine1 + " " + addressLine2;
507	    }
