509	    /**
510	     * Normalizes the submitted {@code telephone} on create to its canonical form (see
511	     * {@link TelephoneNormalizer#normalize}) and writes it back onto the request so it is the value
512	     * stored and returned. Any input that does not reduce to a valid telephone is rejected with a
513	     * {@code 400 Bad Request}.
514	     *
515	     * @param ownerFieldsDto the submitted owner fields (its {@code telephone} is non-blank here,
516	     *                       {@link #rejectBlankOwnerFields} having already run)
517	     * @throws InvalidOwnerFieldsException if the telephone cannot be normalized to a valid value
518	     */
519	    private void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
520	        String normalized = TelephoneNormalizer.normalize(ownerFieldsDto.getTelephone())
521	            .orElseThrow(() -> new InvalidOwnerFieldsException(List.of("telephone")));
522	        ownerFieldsDto.setTelephone(normalized);
523	    }
524	
525	    /**
526	     * Normalizes an optionally-supplied {@code email}. When absent (null) or blank the field is left
527	     * untouched (email is optional). When present it is reduced to its canonical form (see
528	     * {@link EmailNormalizer#normalize}) and written back so it is the value stored and returned. Any
529	     * present-but-invalid address is rejected with a {@code 400 Bad Request}.
530	     *
531	     * @param ownerFieldsDto the submitted owner fields
532	     * @throws InvalidOwnerFieldsException if the email is present but not a syntactically valid address,
533	     *                                     or its domain is on the disposable-domain blocklist
534	     */
535	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
536	        String email = ownerFieldsDto.getEmail();
537	        if (email == null || email.isBlank()) {
538	            return;
539	        }
540	        String normalized = EmailNormalizer.normalize(email)
541	            .orElseThrow(() -> new InvalidOwnerFieldsException(List.of("email")));
542	        if (EmailNormalizer.hasDisposableDomain(normalized)) {
543	            throw new InvalidOwnerFieldsException(List.of("email"));
544	        }
545	        ownerFieldsDto.setEmail(normalized);
546	    }
