548	    /**
549	     * Rejects creating an owner whose derived identity collides with an existing owner. All owner
550	     * duplicate detection is now expressed through the single derived {@code identityKey}
551	     * ({@code sha256hex(normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName))}, see
552	     * {@link OwnerIdentity}), which replaces the previously separate telephone, email and household
553	     * checks. Two owners denote the same person when their whole identity keys are equal, so a create
554	     * is rejected as a {@code 409 Conflict} when another (non-deleted) owner already carries the same
555	     * key. Because the telephone is part of the key, two owners who share a last name and postcode but
556	     * carry different telephones have different keys and are both allowed (they are instead recorded as
557	     * a {@linkplain #findPossibleDuplicate possible duplicate}); an email or a household on its own no
558	     * longer makes a duplicate.
559	     *
560	     * @param ownerFieldsDto the submitted owner fields, with telephone and email already normalized
561	     *                       ({@link #normalizeTelephone}, {@link #normalizeEmail})
562	     * @throws DuplicateOwnerIdentityException if another owner already carries the same identity
563	     */
564	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto) {
565	        String identityKey = OwnerIdentity.identityKey(
566	            ownerFieldsDto.getTelephone(), ownerFieldsDto.getEmail(), ownerFieldsDto.getLastName());
567	        boolean inUse = activeOwners().stream()
568	            .map(OwnerIdentity::identityKey)
569	            .anyMatch(identityKey::equals);
570	        if (inUse) {
571	            throw new DuplicateOwnerIdentityException(identityKey);
572	        }
573	    }
