575	    /**
576	     * The owners considered by duplicate detection: every persisted owner except those flagged
577	     * {@code deleted}. A soft-deleted owner is retained but must never make a later create look like a
578	     * duplicate, so both the hard-duplicate identity check ({@link #rejectDuplicateIdentity}) and the
579	     * soft {@linkplain #findPossibleDuplicate possible-duplicate} match are judged against these owners
580	     * alone. Only owners already persisted (before this create) are included.
581	     *
582	     * @return the non-deleted owners currently persisted
583	     */
584	    private List<Owner> activeOwners() {
585	        return this.clinicService.findAllOwners().stream()
586	            .filter(owner -> !owner.isDeleted())
587	            .toList();
588	    }
