590	    /**
591	     * Counts the existing owners (before this create) whose {@code firstName} and {@code lastName}
592	     * both match the submitted values, compared case-insensitively. The count reflects only owners
593	     * already persisted at the time of the create, so the owner being created is never included.
594	     *
595	     * @param firstName the submitted first name (non-blank here, {@link #rejectBlankOwnerFields}
596	     *                  having already run)
597	     * @param lastName  the submitted last name (non-blank here)
598	     * @return the number of existing owners sharing the same first and last name
599	     */
600	    private int countNamesakes(String firstName, String lastName) {
601	        return (int) this.clinicService.findAllOwners().stream()
602	            .filter(owner -> firstName.equalsIgnoreCase(owner.getFirstName())
603	                && lastName.equalsIgnoreCase(owner.getLastName()))
604	            .count();
605	    }
606	
607	    /**
608	     * Counts the existing owners (before this create) belonging to the given household, i.e. those
609	     * whose stored {@code householdId} equals the value derived for the owner being created. The
610	     * count reflects only owners already persisted at the time of the create, so the owner being
611	     * created is never included; callers add one to obtain the household size after this create.
612	     *
613	     * @param householdId the household identifier derived for the owner being created (see
614	     *                    {@link HouseholdNormalizer#toHouseholdId})
615	     * @return the number of existing owners already sharing that household
616	     */
617	    private int countHouseholdMembers(String householdId) {
618	        return householdMembers(householdId).size();
619	    }
620	
621	    /**
622	     * Returns the existing owners (before this create) belonging to the given household, i.e. those
623	     * whose stored {@code householdId} equals the value derived for the owner being created. As with
624	     * {@link #countHouseholdMembers}, only owners already persisted are included, so the owner being
625	     * created is never among them.
626	     *
627	     * @param householdId the household identifier derived for the owner being created (see
628	     *                    {@link HouseholdNormalizer#toHouseholdId})
629	     * @return the existing owners already sharing that household (empty when {@code householdId} is
630	     *         {@code null})
631	     */
632	    private List<Owner> householdMembers(String householdId) {
633	        if (householdId == null) {
634	            return List.of();
635	        }
636	        return this.clinicService.findAllOwners().stream()
637	            .filter(member -> householdId.equals(member.getHouseholdId()))
638	            .toList();
639	    }
640	
641	    /**
642	     * Caps a new owner's {@code membershipLevel} so it cannot exceed one above the current maximum
643	     * {@code membershipLevel} among their existing household members. The owner's own level is the
644	     * value {@linkplain OwnerMapper#membershipLevel(Owner) it would otherwise report}; it is capped at
645	     * {@code maxHouseholdLevel + 1}. When the household has no existing member no cap applies and the
646	     * owner's own level is returned unchanged.
647	     *
648	     * @param owner the owner being created, already stamped with its household id and size
649	     * @return the (possibly capped) membership level to stamp on the owner
650	     */
651	    private int cappedMembershipLevel(Owner owner) {
652	        int ownLevel = this.ownerMapper.membershipLevel(owner);
653	        OptionalInt maxHouseholdLevel = householdMembers(owner.getHouseholdId()).stream()
654	            .mapToInt(this.ownerMapper::membershipLevel)
655	            .max();
656	        return maxHouseholdLevel.isPresent()
657	            ? Math.min(ownLevel, maxHouseholdLevel.getAsInt() + 1)
658	            : ownLevel;
659	    }
660	
661	    /**
662	     * Derives the address an owner should carry from its submitted fields. The update path stamps an
663	     * owner with an address taken from the request, so routing that through this single method keeps the
664	     * derivation of "the owner's address" in one place, mirroring {@link #householdIdFor} for the
665	     * household id.
666	     *
667	     * @param ownerFieldsDto the submitted owner fields
668	     * @return the address to store on the owner
669	     */
670	    private String addressFor(OwnerFieldsDto ownerFieldsDto) {
671	        return ownerFieldsDto.getAddress();
672	    }
673	
674	    /**
675	     * Derives the household id an owner should carry from its submitted fields (see
676	     * {@link HouseholdNormalizer#toHouseholdId}). Both create and update stamp an owner with a
677	     * household id, so routing them through this single method keeps them agreed on which of the
678	     * owner's fields key the household.
679	     *
680	     * @param ownerFieldsDto the submitted owner fields (its identifying fields are non-blank here,
681	     *                       {@link #rejectBlankOwnerFields} having already run on create)
682	     * @return the owner's household id
683	     */
684	    private String householdIdFor(OwnerFieldsDto ownerFieldsDto) {
685	        return HouseholdNormalizer.toHouseholdId(
686	            ownerFieldsDto.getLastName(), ownerFieldsDto.getPostcode());
687	    }
688	
689	    /**
690	     * Finds an existing owner that the owner being created soft-matches on, or {@code null} when there
691	     * is none. The create has already cleared the hard-duplicate identity check
692	     * ({@link #rejectDuplicateIdentity}), so its {@code identityKey} matches no existing owner; it is a
693	     * <em>possible</em> duplicate when it nevertheless shares an existing owner's {@code postcode} and
694	     * the {@linkplain Soundex#soundex Soundex} of its {@code lastName} while their identity keys still
695	     * differ. Because the telephone is part of the identity key, two owners with the same last name and
696	     * postcode but different telephones have differing keys and so soft-match here rather than colliding
697	     * as a hard duplicate. The oldest such owner (the earliest persisted) is returned so the flag points
698	     * at the original record; owners with no postcode never match, since a shared postcode is required.
699	     *
700	     * @param owner the owner being created, with telephone already normalized and lastName/postcode set
701	     * @return the id of the matching existing owner, or {@code null} when the owner is not a possible
702	     *         duplicate
703	     */
704	    private Integer findPossibleDuplicate(Owner owner) {
705	        String postcode = owner.getPostcode();
706	        if (postcode == null) {
707	            return null;
708	        }
709	        String identityKey = OwnerIdentity.identityKey(owner);
710	        String lastNameCode = Soundex.soundex(owner.getLastName());
711	        return activeOwners().stream()
712	            .filter(existing -> !identityKey.equals(OwnerIdentity.identityKey(existing)))
713	            .filter(existing -> lastNameCode.equals(Soundex.soundex(existing.getLastName())))
714	            .filter(existing -> postcode.equals(existing.getPostcode()))
715	            .map(Owner::getId)
716	            .filter(Objects::nonNull)
717	            .min(Integer::compareTo)
718	            .orElse(null);
719	    }
720	
721	    /**
722	     * Records on the owner being created whether it is a possible (soft) duplicate of an existing
723	     * owner. The match itself is decided by {@link #findPossibleDuplicate}; this method reflects its
724	     * result into the two stored fields, so the interpretation of "is a possible duplicate" lives in
725	     * one place: {@code possibleDuplicateOf} holds the matched owner's id (or {@code null} when there
726	     * is none) and {@code possibleDuplicate} is {@code true} exactly when a match was found. An owner
727	     * that opted in with {@code sharesHousehold} is a declared household member, not a suspected
728	     * duplicate, so it is never flagged.
729	     *
730	     * @param owner           the owner being created, with telephone already normalized and
731	     *                        lastName/postcode set
732	     * @param sharesHousehold whether the request opted in to sharing a household
733	     */
734	    private void markPossibleDuplicate(Owner owner, boolean sharesHousehold) {
735	        Integer possibleDuplicateOf = sharesHousehold ? null : findPossibleDuplicate(owner);
736	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
737	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
738	    }
739	
740	    /**
741	     * Counts how many existing owners already live in the given city. The submitted city is compared
742	     * case-insensitively against every existing owner's stored city. The result drives both the hard
743	     * capacity rejection (see {@link #rejectCityAtCapacity}) and the {@code capacityWarning} flag.
744	     *
745	     * @param city the submitted city (non-blank here, {@link #rejectBlankOwnerFields} having already
746	     *             run)
747	     * @return the number of existing owners whose city matches the submitted city
748	     */
749	    private long countOwnersInCity(String city) {
750	        return this.clinicService.findAllOwners().stream()
751	            .map(Owner::getCity)
752	            .filter(Objects::nonNull)
753	            .filter(city::equalsIgnoreCase)
754	            .count();
755	    }
756	
757	    /**
758	     * Rejects creating an owner whose city already holds {@link #MAX_OWNERS_PER_CITY} or more owners.
759	     * A city that is already at (or over) capacity is reported as a {@code 409 Conflict}.
760	     *
761	     * @param city         the submitted city (used only to report the conflict)
762	     * @param ownersInCity the number of owners the city already holds (see {@link #countOwnersInCity})
763	     * @throws OwnerCityAtCapacityException if the city already contains the maximum number of owners
764	     */
765	    private void rejectCityAtCapacity(String city, long ownersInCity) {
766	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
767	            throw new OwnerCityAtCapacityException(city);
768	        }
769	    }
770	
771	    /**
772	     * Resolves the effective registration date for a create, rolled onto a business day. The
773	     * supplied date is used when present, otherwise the server's current date; either way the result
774	     * is rolled forward to the next Monday when it falls on a Saturday or Sunday (see
775	     * {@link BusinessDayAdjuster#toBusinessDay}). Every value derived from the registration date - the
776	     * stored {@code registrationDate}, the membership number's year segment and the daily
777	     * create-limit's per-day count - is judged on this adjusted date.
778	     *
779	     * @param suppliedRegistrationDate the registration date from the request, or {@code null} to
780	     *                                 default to the server's current date
781	     * @return the effective registration date, guaranteed to fall on a business day
782	     */
783	    /**
784	     * Rejects a create whose supplied {@code registrationDate} lies after the server's current date.
785	     * The raw submitted value is compared against {@link LocalDate#now()} before any business-day
786	     * adjustment; a future date cannot describe a registration that has already happened, so it is
787	     * reported as a {@code 400 Bad Request}. A {@code null} registration date (defaulted to the
788	     * server's current date) and any date on or before today are accepted.
789	     *
790	     * @param suppliedRegistrationDate the registration date from the request, or {@code null} when
791	     *                                 omitted
792	     * @throws InvalidOwnerFieldsException if the supplied date is later than the server's current date
793	     */
794	    private void rejectFutureRegistrationDate(LocalDate suppliedRegistrationDate) {
795	        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
796	            throw new InvalidOwnerFieldsException(List.of("registrationDate"));
797	        }
798	    }
799	
800	    private LocalDate effectiveRegistrationDate(LocalDate suppliedRegistrationDate) {
801	        LocalDate registrationDate =
802	            suppliedRegistrationDate != null ? suppliedRegistrationDate : LocalDate.now();
803	        return BusinessDayAdjuster.toBusinessDay(registrationDate);
804	    }
805	
806	    /**
807	     * Rejects creating an owner once {@link #MAX_OWNERS_PER_DAY} or more owners have already been
808	     * created for the given business day, judged by their stored {@code registrationDate}. Only owners
809	     * already persisted (before this create) are counted, and only those whose {@code registrationDate}
810	     * equals the adjusted registration date; a day at (or over) that limit is reported as a {@code 429
811	     * Too Many Requests}.
812	     *
813	     * @param registrationDate   the create's effective registration date, already rolled onto a
814	     *                           business day by {@link #effectiveRegistrationDate}
815	     * @param registeredThatDay  the number of owners already persisted (before this create) whose
816	     *                           {@code registrationDate} equals {@code registrationDate}
817	     * @throws OwnerDailyRegistrationLimitException if that day has already reached the maximum number of
818	     *                                              owner registrations
819	     */
820	    private void rejectDailyRegistrationLimitReached(LocalDate registrationDate, long registeredThatDay) {
821	        if (registeredThatDay >= MAX_OWNERS_PER_DAY) {
822	            throw new OwnerDailyRegistrationLimitException(registrationDate);
823	        }
824	    }
825	
826	    /**
827	     * Counts the owners already persisted (before this create) whose stored {@code registrationDate}
828	     * equals the given day. This is the shared per-day accumulation both the daily create-limit and the
829	     * bulk-signup warning are judged on.
830	     *
831	     * @param registrationDate the create's effective registration date, already rolled onto a business
832	     *                         day by {@link #effectiveRegistrationDate}
833	     * @return the number of existing owners registered on that day
834	     */
835	    private long countRegisteredOn(LocalDate registrationDate) {
836	        return this.clinicService.findAllOwners().stream()
837	            .map(Owner::getRegistrationDate)
838	            .filter(registrationDate::equals)
839	            .count();
840	    }
841	}
